                "birthdate": "1997-10-08",
                "countryOfResidence": "FRA",
                "phoneNumber": "06011897",
                "gender": "MALE"
            })
        }
    }, function (err, res) {
        if (err) {
            reject(err);
        } else {
            console.log("Setup user response:", res.code);
            resolve();
        }
    });
});

